CALCULATE (
    [Total Activity Minutes SUM],
    KEEPFILTERS(
        'SF Activity Tracker'[Activity Status] = "In Process"
    )
)

CALCULATE (
    DISTINCTCOUNT ( 'SF Contact Completed'[Contact ID] ),
    FILTER (
        'SF Contact Completed',
        'SF Contact Completed'[Is Abandoned] = TRUE
            && 'SF Contact Completed'[Is Outbound] = FALSE
            && 'SF Contact Completed'[Media Type ID] IN { "4", "5" }
    )
)

CALCULATE (
    DISTINCTCOUNT ( 'SF Contact Completed'[Contact ID] ),
    FILTER (
        'SF Contact Completed',
        'SF Contact Completed'[Is Outbound] = FALSE
            && 'SF Contact Completed'[Media Type ID] IN { "4", "5" }
    )
)

CALCULATE (
    DISTINCTCOUNT ( 'SF Contact Completed'[Contact ID] ),
    FILTER (
        'SF Contact Completed',
        'SF Contact Completed'[Is Abandoned] = FALSE
